135	      .circle:hover svg {
136	        opacity: 1;
137	      }
138	    }
139	    @media (prefers-reduced-motion: no-preference) {
140	      svg {
141	        transition:
142	          transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1),
143	          opacity 0.3s ease;
144	      }
145	      .circle:focus-visible svg {
146	        transform: scale(1.05);
147	      }
148	      .circle:active svg {
149	        transform: scale(0.97);
150	      }
