152	        animation: pulse 0.5s ease-out;
153	      }
154	    }
155	    @media (hover: hover) and (prefers-reduced-motion: no-preference) {
156	      .circle:hover:not(:active) svg {
157	        transform: scale(1.05);
158	      }
