234	<body>
235	  <main>
236	    <h1 class="visually-hidden">Animated Circle</h1>
237	    <button type="button" class="circle no-transition" aria-label="Change circle color" aria-describedby="status hint">
238	      <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg">
239	        <circle cx="50" cy="50" r="50" fill="currentColor" stroke="none"/>
240	      </svg>
241	    </button>
242	    <p class="status" id="status" role="status" aria-live="polite">Blue</p>
243	    <p class="hint"><span id="hint"><span class="verb">Click</span> to cycle • <span class="double-verb">Double-click</span> or hold to reset<span class="keys" id="keys"> • <kbd>Shift</kbd>+click reverse • <kbd>↑↓←→</kbd> navigate • <kbd>Home</kbd>/<kbd>End</kbd> jump</span></span> <button type="button" class="help-button" aria-label="Keyboard shortcuts" aria-expanded="false" aria-controls="keys"><span aria-hidden="true">?</span></button></p>
244	    <noscript><p class="hint">JavaScript is required to change the color.</p></noscript>
245	  </main>
246	  <script>
247	    const config = {
248	      colors: ['blue', 'red', 'green', 'amber', 'violet', 'cyan'],
249	      storageKey: 'circle-color',
250	      hapticDuration: 50,
251	      longPressDuration: 500,
252	      keySteps: { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 },
253	    };
254	
255	    const DOM = {
256	      button: document.querySelector('.circle'),
257	      status: document.querySelector('.status'),
258	      helpButton: document.querySelector('.help-button'),
259	      keyHint: document.querySelector('.keys'),
260	      verbSpan: document.querySelector('.hint .verb'),
261	      doubleVerbSpan: document.querySelector('.hint .double-verb'),
262	    };
263	
264	    const state = {
265	      index: 0,
266	      shiftHeld: false,
267	      hoverCapable: true,
268	      reducedMotion: matchMedia('(prefers-reduced-motion: reduce)'),
269	      hoverQuery: matchMedia('(hover: none)'),
270	      longPressTimer: null,
271	      longPressed: false,
272	      pointerType: '',
273	    };
274	
275	    function loadColor() {
276	      try {
277	        return localStorage.getItem(config.storageKey);
278	      } catch {
279	        return null;
280	      }
281	    }
282	
283	    function saveColor(color) {
284	      try {
285	        localStorage.setItem(config.storageKey, color);
286	      } catch {}
287	    }
288	
289	    function applyColor() {
290	      const color = config.colors[state.index];
291	      // The first color is the :root default, so it needs no attribute
292	      if (state.index === 0) delete DOM.button.dataset.color;
293	      else DOM.button.dataset.color = color;
294	      DOM.status.textContent = color[0].toUpperCase() + color.slice(1);
295	    }
296	
297	    function syncFromStorage(color = loadColor()) {
298	      const index = config.colors.indexOf(color);
299	      state.index = index === -1 ? 0 : index;
300	      applyColor();
301	    }
302	
303	    // acknowledge: give feedback even when the color is already the requested one
304	    function setIndex(next, { haptic = false, acknowledge = false } = {}) {
305	      const changed = next !== state.index;
306	      if (!changed && !acknowledge) return;
307	      if (changed) {
308	        state.index = next;
309	        applyColor();
310	        saveColor(config.colors[state.index]);
311	      }
312	
313	      if (haptic && navigator.vibrate) navigator.vibrate(config.hapticDuration);
314	
315	      if (state.reducedMotion.matches) return;
316	      DOM.button.classList.remove('color-changed');
317	      void DOM.button.offsetWidth;
318	      DOM.button.classList.add('color-changed');
319	    }
320	
321	    function changeColor(step) {
322	      setIndex((state.index + step + config.colors.length) % config.colors.length, { haptic: true });
323	    }
324	
325	    function updateDeviceVerbs() {
326	      state.hoverCapable = !state.hoverQuery.matches;
327	      DOM.verbSpan.textContent = state.hoverCapable ? 'Click' : 'Tap';
328	      DOM.doubleVerbSpan.textContent = state.hoverCapable ? 'Double-click' : 'Double-tap';
329	    }
330	
331	    function toggleKeyHintVisibility() {
332	      const expanded = DOM.keyHint.classList.toggle('visible');
333	      DOM.helpButton.setAttribute('aria-expanded', expanded);
334	    }
335	
336	    function syncKeyHint() {
337	      DOM.keyHint.classList.toggle('visible', state.hoverCapable);
338	      DOM.helpButton.setAttribute('aria-expanded', state.hoverCapable);
339	    }
340	
341	    function handleKeyDown(event) {
342	      if (event.key === 'Enter' || event.key === ' ') {
343	        if (!event.repeat) state.shiftHeld = event.shiftKey;
344	        if (event.key === 'Enter' && event.repeat) event.preventDefault();
345	        return;
346	      }
347	
348	      if (event.altKey || event.ctrlKey || event.metaKey) return;
349	
350	      if (event.key in config.keySteps) {
351	        event.preventDefault();
352	        changeColor(config.keySteps[event.key]);
353	      } else if (event.key === 'Home') {
354	        event.preventDefault();
355	        setIndex(0, { haptic: true });
356	      } else if (event.key === 'End') {
357	        event.preventDefault();
358	        setIndex(config.colors.length - 1, { haptic: true });
359	      }
360	    }
361	
362	    function handleEscape(event) {
363	      if (event.key !== 'Escape' || state.hoverCapable) return;
364	      if (DOM.keyHint.classList.contains('visible')) toggleKeyHintVisibility();
365	    }
366	
367	    // Initialize
368	    syncFromStorage();
369	
370	    // Wait two frames to ensure layout is complete before enabling transitions
371	    requestAnimationFrame(() => requestAnimationFrame(() => {
372	      DOM.button.classList.remove('no-transition');
373	    }));
374	
375	    updateDeviceVerbs();
376	    syncKeyHint();
377	    // e.g. a tablet gaining or losing a trackpad/keyboard
378	    state.hoverQuery.addEventListener('change', () => {
379	      updateDeviceVerbs();
380	      syncKeyHint();
381	    });
382	
383	    // Event listeners
384	    function clearLongPressTimer() {
385	      if (state.longPressTimer) clearTimeout(state.longPressTimer);
386	      state.longPressTimer = null;
387	    }
388	
389	    DOM.button.addEventListener('keydown', handleKeyDown);
390	    DOM.button.addEventListener('keyup', (event) => {
391	      if (event.key === ' ') state.shiftHeld = event.shiftKey;
392	    });
393	    DOM.button.addEventListener('blur', () => {
394	      state.shiftHeld = false;
395	      clearLongPressTimer();
396	    });
397	    DOM.button.addEventListener('pointerdown', (event) => {
398	      clearLongPressTimer();
399	      state.longPressed = false;
400	      state.pointerType = event.pointerType;
401	      if (!event.isPrimary || event.button !== 0) return;
402	      // Long press (500ms) resets to first color
403	      state.longPressTimer = setTimeout(() => {
404	        state.longPressTimer = null;
405	        state.longPressed = true;
406	        // Without feedback, a hold on the first color looks like it did nothing
407	        setIndex(0, { haptic: true, acknowledge: true });
408	      }, config.longPressDuration);
409	    });
410	    // Prevent context menu during touch long-press; handle Ctrl+click on macOS
411	    DOM.button.addEventListener('contextmenu', (event) => {
412	      if (state.pointerType === 'mouse') {
413	        // Ctrl+click opens context menu without firing pointerup
414	        clearLongPressTimer();
415	      } else if (state.longPressTimer || state.longPressed) {
416	        event.preventDefault();
417	      }
418	    });
419	    DOM.button.addEventListener('pointerup', clearLongPressTimer);
420	    DOM.button.addEventListener('pointercancel', clearLongPressTimer);
421	    DOM.button.addEventListener('pointerleave', clearLongPressTimer);
422	    DOM.button.addEventListener('click', (event) => {
423	      clearLongPressTimer();
424	      // Detect if click resulted from completing a long press (detail > 0) or double-click (detail > 1)
425	      const afterLongPress = state.longPressed && event.detail !== 0;
426	      state.longPressed = false;
427	      const reverse = event.shiftKey || state.shiftHeld;
428	      // Reset before any early return so a stale Shift can't reverse a later click
429	      state.shiftHeld = false;
430	      if (afterLongPress || event.detail > 1) return;
431	      changeColor(reverse ? -1 : 1);
432	    });
433	    DOM.button.addEventListener('dblclick', () => {
434	      // Match long-press feedback, since both are advertised as "reset"
435	      setIndex(0, { haptic: true, acknowledge: true });
436	    });
437	    DOM.button.addEventListener('animationend', () => {
438	      DOM.button.classList.remove('color-changed');
439	    });
440	
441	    DOM.helpButton.addEventListener('click', toggleKeyHintVisibility);
442	    // On the document so it also works from the help button that opened the hint
443	    addEventListener('keydown', handleEscape);
444	
445	    addEventListener('storage', (event) => {
446	      // Sync if changed key matches or if entire storage was cleared (key === null)
447	      if (event.key !== config.storageKey && event.key !== null) return;
448	      syncFromStorage(event.newValue);
449	    });
450	    // Storage events are not delivered while the page sits in the bfcache
451	    addEventListener('pageshow', (event) => {
452	      if (event.persisted) syncFromStorage();
453	    });
454	  </script>
455	</body>
456	</html>
