DOM.button.addEventListener('keydown', handleKeyDown);
DOM.button.addEventListener('keyup', (event) => {
  if (event.key === ' ') state.shiftHeld = event.shiftKey;
});
DOM.button.addEventListener('blur', () => {
  state.shiftHeld = false;
  clearLongPressTimer();
});
DOM.button.addEventListener('pointerdown', (event) => {
  clearLongPressTimer();
  state.longPressed = false;
  state.pointerType = event.pointerType;
  if (!event.isPrimary || event.button !== 0) return;
  // Long press (500ms) resets to first color
  state.longPressTimer = setTimeout(() => {
    state.longPressTimer = null;
    state.longPressed = true;
    // Without feedback, a hold on the first color looks like it did nothing
    setIndex(0, { haptic: true, acknowledge: true });
  }, config.longPressDuration);
});
// Prevent context menu during touch long-press; handle Ctrl+click on macOS
DOM.button.addEventListener('contextmenu', (event) => {
  if (state.pointerType === 'mouse') {
    // Ctrl+click opens context menu without firing pointerup
    clearLongPressTimer();
  } else if (state.longPressTimer || state.longPressed) {
    event.preventDefault();
  }
});
DOM.button.addEventListener('pointerup', clearLongPressTimer);
DOM.button.addEventListener('pointercancel', clearLongPressTimer);
DOM.button.addEventListener('pointerleave', clearLongPressTimer);

